import { useState } from 'react';
import { Box, Tabs, Tab, Typography, Grid } from '@mui/material';
import { useTheme, styled } from '@mui/material/styles';
import TabSection2 from '../sections/tabSection2';

const SimpleTab1 = ({ tabsData, imageShow }) => {
    const theme = useTheme();
    const [value, setValue] = useState(0);

    const handleChange = (event, newValue) => {
        setValue(newValue);
    };

    return (
        <>
            <Grid container justifyContent="left" sx={{ background: theme.palette.text.primary, py: 0 }}>
                <Grid item xs={12}>
                    <Tabs
                        value={value}
                        onChange={handleChange}
                        sx={{
                            '& .MuiTabs-indicator': { display: 'none' },
                            '& .MuiTabs-flexContainer': {
                                gap: 1,
                                position: 'relative',
                                flexWrap: { xs: 'wrap', md: 'nowrap' }, // Responsive wrapping
                                justifyContent: 'left',
                                border: 'none'
                            }
                        }}
                    >
                        {tabsData.map((tab, index) => (
                            <Tab
                                key={index}
                                sx={{
                                    minHeight: 'auto',
                                    minWidth: 'auto',
                                    alignItems: 'center',
                                    padding: '14px 15px',
                                    textTransform: 'none',
                                    borderRadius: '4px',
                                    border:
                                        value === index
                                            ? `2px solid ${theme.palette.secondary.dark}`
                                            : `2px solid ${theme.palette.secondary.dark}`,
                                    backgroundColor: value === index ? theme.palette.text.primary : theme.palette.secondary.dark,
                                    '&:hover': {
                                        backgroundColor: theme.palette.text.primary,
                                        '& .MuiBox-root': {
                                            color: theme.palette.secondary.dark
                                        }
                                    },
                                    '& .MuiTab-wrapper': {
                                        flexDirection: 'row',
                                        alignItems: 'center',
                                        gap: '8px'
                                    },
                                    flexShrink: 0 // Prevents tabs from shrinking
                                }}
                                label={
                                    <Box
                                        sx={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: '8px',
                                            color: value === index ? theme.palette.primary.main : theme.palette.common.white,
                                            transition: 'all 0.3s ease'
                                        }}
                                    >
                                        {tab.icon}
                                        <Typography
                                            variant="body1"
                                            fontWeight={600}
                                            noWrap
                                            sx={{
                                                display: 'inline-block',
                                                maxWidth: '100%',
                                                overflow: 'hidden',
                                                textOverflow: 'ellipsis'
                                            }}
                                        >
                                            {tab.label}
                                        </Typography>
                                    </Box>
                                }
                            />
                        ))}
                    </Tabs>
                </Grid>
                <Grid item xs={12}>
                    <TabSection2 title={tabsData[value].label} description={tabsData[value].description} imageShow={false} />
                </Grid>
            </Grid>
        </>
    );
};

export default SimpleTab1;
